function rateGrid(p){if(['period','fixed'].includes(p.rentalPricingMode))return periodPrice(p);if(!rentalScopeConfirmed)return '<p class="rental-price-pending">Velg bruk for å se leiepris</p>';if(p.priceOnRequest)return '<p class="quote-only"><strong>Pris på forespørsel</strong><small>Du får et samlet, uforpliktende tilbud.</small></p>';const days=rentalDays(el('start')?.value||'',el('end')?.value||''),plan=days===null?null:ratePlan(p,days,products);return `${plan?`<div class="rental-period-price"><span>Valgt leieperiode · ${days} døgn</span><strong>${money(plan.total)}</strong></div>`:''}<div class="rate-grid"><div><span>Døgn</span><strong>${money(p.price)}</strong></div><div><span>Uke · 7 døgn</span><strong>${money(p.weekPrice??p.price*5)}</strong></div><div><span>Måned · 30 døgn</span><strong>${money(p.monthPrice??p.price*15)}</strong></div></div><p class="rate-caption">Leiepriser inkl. mva. Tilgjengelighet bekreftes i tilbudet.</p>`;}
