function addonPrice(p){if(addonUnit(p)&&p.rentalPricingMode==='period'&&!p.priceOnRequest)return textilePriceLabel(p);if(p.rentalPricingMode==='period'&&!p.priceOnRequest)return '+ '+money(p.price)+' per pakke inntil 30 dager · inkl. mva. Ny pris per påbegynte 30 dager.';return p.priceOnRequest?'Pris på forespørsel':`+${money(p.price)}/døgn per pakke`;}
