 return `<section class="proposal-options"><h3>Servise som følger med</h3><p class="hint">Middagstallerken, suppeskål og desserttallerken følger alltid samlet. Én av hver per person.</p>${(p.components||[]).map(c=>{const x=products.find(x=>x.id===c.id);return `<div class="proposal-included-line"><strong>${html(x?.name)}</strong><span><b data-proposal-count data-per-person="${c.quantity}">4</b> stk.</span></div>`;}).join('')}<fieldset class="rental-options"><legend>2. Bestikk og glass</legend><p class="hint">Forslaget inkluderer bestikk, vannglass og rødvinsglass. Du kan velge bort tilvalg, velge én eller flere typer vinglass eller legge til andre glass. Antall følger antall personer.</p><div class="addon-choices">${primary.map(x=>row(x,`<input type="checkbox" name="packageAddon" value="${x.id}" ${defaults.has(x.id)?'checked':''}>`)).join('')}</div></fieldset><fieldset class="rental-options"><legend>Vinglass (valgfritt)</legend><p class="hint">Rødvinsglass er foreslått. Velg gjerne hvitvinsglass i tillegg, eller fjern krysset ved rødvinsglass.</p><div class="addon-choices">${wine.map(x=>row(x,`<input type="checkbox" name="packageAddon" value="${x.id}" ${defaults.has(x.id)?'checked':''}>`)).join('')}</div></fieldset>${additional.length?`<fieldset class="rental-options"><legend>Andre glass (valgfritt)</legend><div class="addon-choices">${additional.map(x=>row(x,`<input type="checkbox" name="packageAddon" value="${x.id}" ${defaults.has(x.id)?'checked':''}>`)).join('')}</div></fieldset>`:''}</section>`;
