let cart={};try{const saved=JSON.parse(localStorage.getItem('konsept-cart-v1')||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))cart=saved;}catch{}
let packageGroups=[];try{packageGroups=JSON.parse(localStorage.getItem('konsept-package-groups-v1')||'[]');}catch{}
let sofaSetups=[],savedSofas=null;try{const saved=JSON.parse(localStorage.getItem('konsept-sofas-v1')||'null');if(Array.isArray(saved))savedSofas=saved.filter(s=>s&&typeof s.id==='string'&&typeof s.series==='string'&&s.selection&&typeof s.selection==='object'&&!Array.isArray(s.selection)&&Object.values(s.selection).every(q=>Number.isInteger(q)&&q>0&&q<=99)).slice(0,50);}catch{}
let filter='Alle',tableFilter='';const el=id=>document.getElementById(id);const money=n=>new Intl.NumberFormat('nb-NO').format(n)+' kr';
function moduleGroups(){return [...new Set(products.filter(p=>p.moduleSeries&&!p.isPackage).map(p=>p.moduleSeries))];}
function catalogLink(category='Alle',area=purpose){const params=new URLSearchParams({bruk:validPurpose(area)});if(category!=='Alle')params.set('kategori',category);return '/utvalg.html?'+params+'#utvalg';}
function renderOccasionLanding(){if(!isOccasionPage||new URL(location.href).searchParams.get('anledning')==='boligfoto'||new URL(location.href).searchParams.get('bruk')==='boligsalg')return;const entries={boligfoto:['Boligfoto og visning','boligsalg','Til boligfoto og visning tilbyr vi enkeltprodukter som du setter sammen selv. Ønsker du en komplett løsning, kan du be om tilbud på fullstyling eller delstyling.'],messe:['Møbler til messe og event','messe','Møbler og innredning til messestands, arrangementer, mingleområder og besøkssoner. Velg enkeltprodukter eller ta utgangspunkt i en ferdig pakke.'],bryllup:['Møbler til bryllup og fest','fest','Møbler, servise og dekor til feiringen. Velg selv eller ta utgangspunkt i en ferdig pakke.'],jul:['Julepynt og møbler til jul og sesong','jul','Gjør klart til sesongen med møbler, dekor og ferdige juleoppsett.'],bedrift:['Møbler til bedrift og midlertidige rom','bedrift','Skap innbydende pauserom, venterom, lobbyer, resepsjoner og fellesområder. Velg enkeltmøbler eller en samlet løsning tilpasset arbeidsplassen.'],alle:['Møbler til alle bruksområder','alle','Utforsk hele utvalget, eller ta utgangspunkt i en ferdig pakke.']};const requestedKey=new URL(location.href).searchParams.get('anledning')||'alle';const key=requestedKey==='event'?'messe':requestedKey;const [title,area,intro]=entries[key]||entries.alle;document.title=title+' | Konseptuell';const individual=catalogLink('Enkeltprodukter',area),packages=new URL(catalogLink('Pakker',area),location.origin);el('occasionLanding').innerHTML=`<a class="text-button" href="/">← Velg et annet bruksområde</a><p class="eyebrow">HVA SKAL DU LEIE TIL?</p><h1>${html(title)}</h1><p class="occasion-intro">${html(intro)}</p>${key==='bedrift'?'<p class="occasion-intro">Utvalgte bedriftspakker kan leies med kjøpsmulighet etter leieperioden. Leiepris og kjøpspris avtales før leien starter. Tilpassede løsninger prises når vi utarbeider leietilbudet.</p>':''}<div class="occasion-choice-grid${key==='bedrift'?' business-package-first':''}">${['messe','bryllup','jul','bedrift'].includes(key)?`<a href="${html(packages.pathname+packages.search+packages.hash)}"><span class="eyebrow">TA UTGANGSPUNKT I ET OPPSETT</span><h2>Se ferdige pakker</h2><p>${key==='boligfoto'?'Her tilbyr vi enkeltprodukter som du setter sammen selv. For komplette løsninger kan du kontakte oss om fullstyling eller delstyling.':'Utforsk sammensatte løsninger. Innhold og omfang tilpasses og avklares i tilbudet.'}</p><b>${key==='boligfoto'?'Se mulighetene':'Finn pakker'} <span aria-hidden="true">↗</span></b></a><a class="occasion-individual" href="${html(individual)}"><span class="eyebrow">SETT SAMMEN SELV</span><h2>Se enkeltprodukter</h2><p>Velg møbler, interiør og dekor enkeltvis. Sett sammen ditt eget utvalg og oppgi antall og leieperiode.</p><b>Finn produkter <span aria-hidden="true">↗</span></b></a>`:`<a class="occasion-individual" href="${html(individual)}"><span class="eyebrow">SETT SAMMEN SELV</span><h2>Se enkeltprodukter</h2><p>Velg møbler, interiør og dekor enkeltvis. Sett sammen ditt eget utvalg og oppgi antall og leieperiode.</p><b>Finn produkter <span aria-hidden="true">↗</span></b></a><a href="${html(packages.pathname+packages.search+packages.hash)}"><span class="eyebrow">TA UTGANGSPUNKT I ET OPPSETT</span><h2>Se ferdige pakker</h2><p>${key==='boligfoto'?'Her tilbyr vi enkeltprodukter som du setter sammen selv. For komplette løsninger kan du kontakte oss om fullstyling eller delstyling.':'Utforsk sammensatte løsninger. Innhold og omfang tilpasses og avklares i tilbudet.'}</p><b>${key==='boligfoto'?'Se mulighetene':'Finn pakker'} <span aria-hidden="true">↗</span></b></a>`}</div><aside class="occasion-help"><h3>Trenger du hjelp til å finne det rette?</h3><p>Vi har mange tusen artikler utover nettutvalget. Fortell oss hva du trenger.</p><button type="button" class="text-button" data-occasion-custom>Be om et tilpasset forslag ↗</button></aside>`;el('occasionLanding').querySelector('[data-occasion-custom]').addEventListener('click',openCustomRequest);}
function renderRentalHome(){const product=id=>products.find(p=>p.id===id&&p.active),home=getSiteSettings().home,areas={boligfoto:'boligsalg',messe:'messe',bryllup:'fest',jul:'jul',bedrift:'bedrift',alle:'alle'};el('homeUseCases').innerHTML=home.occasions.map(c=>{const p=product(c.productId),src=c.image||p?.image||'/assets/hero.jpg',href=c.id==='boligfoto'?catalogLink('Enkeltprodukter','boligsalg'):c.id==='alle'?'/utvalg.html?bruk=alle#utvalg':'/anledning.html?bruk='+areas[c.id]+'&anledning='+c.id;return `<a href="${html(href)}"><figure><img src="${html(src)}" alt="" loading="lazy" decoding="async"><span>${isKiPhoto(src)?kiDisclosure:'Illustrasjonsbilde'}</span></figure><div><h3>${html(c.title)}</h3><span aria-hidden="true">↗</span></div></a>`;}).join('');const selected=home.products.map(product).filter(Boolean);el('homeProducts').innerHTML=selected.map(p=>`<article><button class="rental-product-photo" type="button" data-detail="${html(p.id)}" aria-label="Se detaljer om ${html(productTitle(p))}"><img src="${html(p.image)}" alt="${html(productTitle(p))}" loading="lazy" decoding="async"></button><div class="rental-product-copy"><h3>${html(productTitle(p))}</h3><p>${html(p.material)}</p>${rateGrid(p)}<p class="hint">Tilgjengelighet for dine datoer bekreftes i tilbudet.</p><button type="button" class="text-button" data-detail="${html(p.id)}">Se produkt og velg antall ↗</button></div></article>`).join('');}
function syncCatalogCategories(){const group=document.querySelector('[data-filter]')?.parentElement;if(!group)return;const categories=getSiteSettings().categories.filter(c=>['Bord','Senger','Sofaer','Stoler','Utemøbler','Servise','Pakker','Bilder','Hyller','Belysning','Tepper','Kunstige planter','Kunstige blomster','Dekor'].includes(c.id)||products.some(p=>p.category===c.id&&!p.addonOnly&&!p.isService));group.innerHTML='<button type="button" data-filter="Alle">Alle</button>'+categories.map(c=>'<button type="button" data-filter="'+html(c.id)+'">'+html(c.label==='Pakker'?'Ferdige pakker':c.label)+'</button>').join('');for(const b of group.querySelectorAll('[data-filter]')){b.classList.toggle('active',b.dataset.filter===filter);b.setAttribute('aria-pressed',String(b.dataset.filter===filter));}}

function renderHome(){if(isProductPage||isCatalogPage||isOccasionPage)return;renderRentalHome();for(const link of document.querySelectorAll('.home-catalog-link'))link.href=catalogLink(link.dataset.category||'Alle',link.dataset.area||purpose);const picks=getSiteSettings().home.packages.map(id=>products.find(p=>p.id===id&&p.active)).filter(Boolean);el('homePackages').innerHTML=picks.map(p=>`<article><button type="button" class="home-package-photo" data-detail="${html(p.id)}" aria-label="Se detaljer om ${html(productTitle(p))}"><img src="${html(p.image)}" alt="${html(productTitle(p))}" loading="lazy" decoding="async"><span class="home-example">${isKiPhoto(p.image)?kiDisclosure:'Bildet viser et eksempel'}</span></button><div class="home-package-copy"><h3>${html(productTitle(p))}</h3>${['left','right','end'].includes(p.moduleRole)?`<p class="module-end-note">${p.moduleRole==='end'?'Universell ende · maks to per sofa':p.moduleRole==='left'?'Venstre ende · maks én per sofa':'Høyre ende · maks én per sofa'}</p>`:''}<p>${html(p.material)}</p>${rateGrid(p)}<button type="button" class="text-button" data-detail="${html(p.id)}">Se pakken og tilpass ↗</button></div></article>`).join('')||'<p>Vi hjelper deg å sette sammen en løsning. Fortell oss hva du trenger.</p>';const home=getSiteSettings().home;const tree=products.find(p=>p.active&&p.id===home.seasonProductId)||(!home.seasonProductId?products.find(p=>p.active&&isChristmasTreePackage(p)):null);const theme=products.find(p=>p.active&&isCustomPackage(p)&&p.name.startsWith('Temafest'));const month=new Date().getMonth()+1;const inSeason=home.seasonEnabled&&(home.seasonFromMonth<=home.seasonToMonth?month>=home.seasonFromMonth&&month<=home.seasonToMonth:month>=home.seasonFromMonth||month<=home.seasonToMonth);el('homeSeason').hidden=!tree||!inSeason;if(tree&&inSeason)el('homeSeason').innerHTML=`<figure><img src="${html(tree.image)}" alt="Inspirasjon til et ferdig pyntet juletre" loading="lazy" decoding="async"><figcaption>${kiDisclosure} · pynt og uttrykk kan variere</figcaption></figure><div><p class="eyebrow">SESONGENS HØYDEPUNKT</p><h2>Snart jul.<br><em>Vi skaper stemningen.</em></h2><p>Gjør arbeidsplassen, hjemmet eller julefesten klar for sesongen. Vi leverer ferdig oppsatte og pyntede juletrær, og kan hjelpe med styling og julepynt i flere områder.</p><p>Med «Klart til jul» velger du juletre i 180, 210 eller 240 cm. Ønsker du en helhet rundt julefesten, setter vi sammen et forslag etter dine ønsker.</p><p class="hint">Juletre, fot, lys, pynt, levering, oppsett, nedpakking og henting er inkludert i fastprisen.</p><div class="season-actions"><button type="button" class="button light" data-detail="${html(tree.id)}">Se Klart til jul <span aria-hidden="true">↗</span></button>${theme?`<button type="button" class="button button-outline" data-detail="${html(theme.id)}">Planlegg julefesten <span aria-hidden="true">↗</span></button>`:''}</div></div>`;}
function isCustomPackage(p){return !!p?.isPackage&&!!p.components?.length&&p.components.every(c=>products.find(x=>x.id===c.id)?.isService===true);}
function productTitle(p){return isTablewareRental(p,products)?'Servisepakke – sett sammen per person':p.name;}
