document.addEventListener('click',e=>{const build=e.target.closest('[data-build]');if(build){openModuleBuilder(build.dataset.build);return;}const change=e.target.closest('[data-module-change]');if(change){const id=change.dataset.moduleChange,config=builderConfig();if(config.modules.find(p=>p.id===id)?.moduleRequired)return;const next=(moduleSelection[id]||0)+Number(change.dataset.moduleDelta);if(next>=0&&next<=remaining(id,config.base,products)&&next<=moduleQuantityLimit(config.modules,moduleSelection,config.modules.find(p=>p.id===id))){moduleSelection[id]=next;renderModuleBuilder();}return;}const preset=e.target.closest('[data-module-preset]');if(preset){const choice=builderPresets()[Number(preset.dataset.modulePreset)],config=builderConfig({});const selection=choice&&modulePreset(config.modules,choice.ends,choice.middle);if(selection&&builderConfig(selection).valid){moduleSelection=selection;renderModuleBuilder();}}});
el('saveModules').addEventListener('click',()=>{const textile=moduleTextileProduct(),candidate={id:editingSofaId||crypto.randomUUID(),series:moduleSeries,selection:Object.fromEntries(Object.entries(moduleSelection).filter(([,q])=>q>0)),textileId:moduleTextile?textile?.id||'':''};const next=saveSofa(sofaSetups,cart,products,candidate,editingSofaId);if(!next){toast('Oppsettet kan ikke legges til. Andre oppsett og produkter bruker samme beholdning.');return;}sofaSetups=next.setups;cart=next.cart;renderProducts();renderCart();closeSurface(el('modules'));if(isProductPage)renderModuleBuilder();addedNotice(editingSofaId?'Oppsettet er oppdatert':'Oppsettet er lagt til. Du kan legge til flere.');});
function setupText(s){return products.filter(p=>s.selection[p.id]).map(p=>`${s.selection[p.id]} × ${p.name}`).join(' · ');}
function sofaCards(){return sofaSetups.map((s,i)=>{const c=sofaConfiguration({...s,textileId:''},{},products),textile=s.textileId?products.find(p=>p.id===s.textileId):null;const row=sofaCartRow({setup:s,index:i,modules:c.modules,count:c.count,width:c.width,widthKnown:c.widthKnown,priceText:c.priceOnRequest?'Pris på forespørsel':money(c.price)+' / døgn · '+money(c.weekPrice)+' / uke · '+money(c.monthPrice)+' / måned'});return textile?`<div class="cart-product-group has-addons">${row}${cartItem(textile,s,{[textile.id]:1},s.id)}</div>`:row;}).join('')+(sofaSetups.length?`<button type="button" class="cart-line-action sofa-add-another" data-build="${html(sofaSetups.at(-1).series)}">+ Legg til ${outdoorSeries(sofaSetups.at(-1).series)?'et loungeoppsett':'en sofa'} til</button><p class="hint cart-common-info">Leiepriser inkl. mva. Tilgjengelighet bekreftes i tilbudet.</p>`:'');}
