function packageCartCard(g){
 const buy=businessChoices[g.packageId]==='buy',locked=g.product?.packageEditable===false,quoted=g.custom&&g.product?.packageCustomPricing==='quote',rates=packageGroupRates(g,products),days=rentalDays(el('start').value,el('end').value),period=packageGroupPeriodTotal(g,products,days);
 const row=([id,q],extra=false)=>{const p=products.find(x=>x.id===id);if(!p)return '';return `<div class="package-cart-line ${extra||p.addonOnly?'package-cart-addon':''}">${cartThumbnail(p)}<div class="package-cart-copy"><h4>${html(p.name)}</h4><small>${extra?'Tilvalg til':'Tilhører'} ${html(g.name)}</small>${['period','fixed'].includes(p.rentalPricingMode)?periodPrice(p):`<p>${p.priceOnRequest?'Pris på forespørsel':money(p.price)+' / døgn per stk.'}</p>`}<button type="button" class="remove" data-package-item="${html(g.id)}" data-package-product="${id}" data-package-set="0" ${buy||locked?'disabled':''} aria-label="Fjern ${html(p.name)} fra ${html(g.name)}">Fjern fra pakken</button></div><div class="quantity"><button type="button" data-package-item="${html(g.id)}" data-package-product="${id}" data-package-set="${q-1}" ${buy||locked?'disabled':''} aria-label="Færre ${html(p.name)} i ${html(g.name)}">−</button><output aria-label="Antall ${html(p.name)} i ${html(g.name)}">${q}</output><button type="button" data-package-item="${html(g.id)}" data-package-product="${id}" data-package-set="${q+1}" ${buy||locked?'disabled':''} aria-label="Flere ${html(p.name)} i ${html(g.name)}">+</button></div></div>`;};
 return `<section class="package-cart-card" aria-label="${g.custom?'Tilpasset fra ':''}${html(g.name)}"><div class="package-cart-head"><div><p class="eyebrow">${g.custom?'TILPASSET PAKKE':'FERDIG PAKKE'}</p><h3>${g.custom?'Tilpasset fra ':''}${html(g.name)}</h3>${!g.custom?businessCartChoice(g.product):''}</div><button type="button" class="remove" data-package-remove="${html(g.id)}">Fjern hele pakken</button></div>${!g.custom?`<div class="package-cart-count"><span>Antall pakker</span><div class="quantity"><button type="button" data-package-count="${g.packageId}" data-package-delta="-1" aria-label="Færre pakker av ${html(g.name)}">−</button><output>${g.quantity}</output><button type="button" data-package-count="${g.packageId}" data-package-delta="1" aria-label="Flere pakker av ${html(g.name)}" ${remaining(g.packageId,cart,products)>0?'':'disabled'}>+</button></div></div>`:''}<p class="package-cart-notice">${locked?'Pakkens faste innhold kan ikke endres. Antall pakker kan endres, eller hele pakken fjernes.':buy?'Kjøpspris gjelder pakkens faste innhold. Velg leie for å tilpasse enkeltproduktene; kjøp av tilpasset innhold avklares i tilbudet.':g.custom?'Prisen beregnes fra produktene nedenfor. Eventuell pakkerabatt gjelder ikke.':'Produktene nedenfor følger med. Endrer du innholdet, beregnes ny pris som enkeltprodukter.'}</p>${receiptEntries([...Object.entries(g.selection).map(([id,q])=>({id,quantity:q,extra:!!products.find(p=>p.id===id)?.addonOnly})),...Object.entries(g.extras||{}).map(([id,q])=>({id,quantity:q,extra:true}))].map(line=>({...line,addonFor:line.extra?Object.keys(g.selection).filter(id=>products.find(p=>p.id===id)?.relatedAddOns?.includes(line.id)).map(id=>({id})):[]}))).filter(e=>e.type==='line').map(e=>row([e.line.id,e.line.quantity],e.line.extra)).join('')}<div class="package-cart-total"><strong>${buy?'Kjøpspris for pakken':g.custom?'Pris for tilpasset innhold':'Pakkepris'}${g.quantity>1&&!g.custom?' · '+g.quantity+' pakker':''}</strong>${buy?`<p>${packagePurchasePrice(g.product,g.quantity)===null?'Avklares i tilbudet':money(packagePurchasePrice(g.product,g.quantity))}</p>`:rates.priceOnRequest||quoted?'<p>Pris på forespørsel</p>':g.product.rentalPricingMode==='fixed'&&!g.custom?periodPrice({...g.product,price:g.product.price*g.quantity}):`<p>${money(rates.price)} / døgn · ${money(rates.weekPrice)} / uke · ${money(rates.monthPrice)} / måned</p>${days?`<p>Valgt leieperiode: <strong>${period===null?'Avklares i tilbudet':money(period)}</strong></p>`:''}`}<small>Inkl. mva.${g.extras&&Object.keys(g.extras).length?' · Valgfrie tilvalg kommer i tillegg.':''}</small></div></section>`;
}
function applyPackageChange(next){if(!next){toast('Endringen kan ikke gjennomføres. Sjekk beholdning og eventuelle tilvalg som krever et hovedprodukt.');return;}cart=next.basket;packageGroups=next.groups;for(const link of Object.values(cartLinks)){if(link.packageAllocations)for(const id of Object.keys(link.packageAllocations))if(!cart[id])delete link.packageAllocations[id];if(link.packageQuantity!==undefined&&!cart[link.parentId]){link.packageQuantity=0;link.parentId='';}}renderCart();renderProducts();}
document.addEventListener('click',event=>{
 const item=event.target.closest('[data-package-item]'),remove=event.target.closest('[data-package-remove]'),count=event.target.closest('[data-package-count]');
 if(item||remove||count){event.preventDefault();event.stopImmediatePropagation();
  if(item){const id=item.dataset.packageItem,pid=id.startsWith('fixed:')?id.slice(6):packageGroups.find(g=>g.id===id)?.packageId;if(businessChoices[pid]==='buy'||products.find(p=>p.id===pid)?.packageEditable===false)return;const next=changePackageItem(cart,products,packageGroups,id,item.dataset.packageProduct,Number(item.dataset.packageSet),cartLinks);if(next&&businessChoices[pid]==='try')for(const g of next.groups)if(g.packageId===pid)g.acquisition='try';applyPackageChange(next);}
  if(remove)applyPackageChange(removePackageGroup(cart,products,packageGroups,remove.dataset.packageRemove,cartLinks));
  if(count){const id=count.dataset.packageCount,q=(cart[id]||0)+Number(count.dataset.packageDelta);if(q===0){applyPackageChange(removePackageGroup(cart,products,packageGroups,'fixed:'+id,cartLinks));return;}const next=cartChange(cart,products,id,q);if(next&&validPackageBasket(next,products))applyPackageChange({basket:next,groups:packageGroups});else toast('Det er ikke nok ledige produkter til flere pakker.');}return;
 }
 // Independent lines may share a product with a customised package or a sofa setup.
 const r=event.target.closest('[data-remove]'),q=event.target.closest('[data-quantity]'),id=r?.dataset.remove||q?.dataset.quantity;if(!id)return;
 const free=loosePackageBasket(),reserved=(cart[id]||0)-(free[id]||0);if(!reserved)return;
 event.preventDefault();event.stopImmediatePropagation();const amount=r?reserved:(cart[id]||0)+Number(q.dataset.delta);if(q&&amount<reserved)return;const next=cartChange(cart,products,id,amount);if(next&&validPackageBasket(next,products)){cart=next;renderCart();renderProducts();}else toast('Endringen kan ikke gjennomføres med valgt beholdning og tilvalg.');
},true);

function cartItem(p,parent=null,basket=cart,sofaId=''){if(p.isProposal)return `<div class="cart-item proposal-cart"><div class="thumb">${cartThumbnail(p)}</div><div class="item-copy"><h3>${html(productTitle(p))}</h3><p class="hint">Serviset følger samlet. Antall personer: ${basket[p.id]}</p>${(p.components||[]).map(c=>{const x=products.find(x=>x.id===c.id);return `<div class="proposal-included-line"><strong>${html(x?.name)}</strong><span>${basket[p.id]*c.quantity} stk.</span></div>`;}).join('')}<p>Pris på forespørsel</p><button class="remove" data-remove="${p.id}" aria-label="Fjern ${html(productTitle(p))}">Fjern serviset</button></div><div class="quantity"><button data-quantity="${p.id}" data-delta="-1" aria-label="Færre personer" ${basket[p.id]<=p.minimumQuantity?'disabled':''}>−</button><span>${basket[p.id]}</span><button data-quantity="${p.id}" data-delta="1" aria-label="Flere personer" ${remaining(p.id,cart,products)<=0?'disabled':''}>+</button></div></div>`;let available=basket[p.id];const raw=Array.isArray(cartLinks[p.id]?.choices)?cartLinks[p.id].choices:[];const choices=raw.map(c=>{const quantity=Math.min(available,Number.isInteger(c.quantity)&&c.quantity>0?c.quantity:0);available-=quantity;return {...c,quantity};}).filter(c=>c.quantity>0);if(isWall(p)||p.rentalPricingMode==='period')choices.length=0;if(raw.length&&available>0&&!isWall(p)&&p.rentalPricingMode!=='period')choices.push({quantity:available,color:isWall(p)?'Uttrykk avklares med stylist':'Farge og dyner avklares'});return `<div class="cart-item ${parent?'cart-addon':''}">${parent?`<p class="cart-addon-label"><span aria-hidden="true">↳</span> ${parent.isProposal&&basket[p.id]>basket[parent.id]&&products.some(x=>x.isProposal&&x.id!==parent.id&&basket[x.id]&&x.relatedAddOns?.includes(p.id))?'Felles tilvalg til valgte serviseoppsett':'Tilvalg'}</p>`:''}<div class="thumb">${cartThumbnail(p)}</div><div class="item-copy"><h3>${html(p.rentalPricingMode==='period'?productTitle(p).split(' – ')[0]:productTitle(p))}</h3>${parent&&p.rentalPricingMode==='period'?'<p class="cart-addon-composition">'+(addonUnit(p)?html(p.description):'Stylistens sammensetning · '+basket[p.id]+' sett')+'</p>':''}${businessCartChoice(p)}${businessPackageIds.has(p.id)&&businessChoices[p.id]?businessPurchaseSummary(p,basket[p.id]):''}${['period','fixed'].includes(p.rentalPricingMode)?periodPrice(p):`<p>${businessChoices[p.id]==='buy'?'Kjøp · pris som angitt over':p.priceOnRequest?'Pris på forespørsel':`${money(p.price)} / døgn · ${money(p.weekPrice??p.price*5)} / uke · ${money(p.monthPrice??p.price*15)} / måned`}</p>`}${choices.length?`<p class="cart-addon-details">${choices.map(c=>`${html(c.quantity)} ${isWall(p)?'bildevegg(er)':'sett'}: ${html(c.color)}${c.duvets?' · '+html(c.duvets):''}`).join('<br>')}</p>`:''}${isWall(p)?'<p class="cart-addon-details">Stylisten setter sammen helheten. Størrelser og plassering kan variere; helhetsuttrykket beholdes.</p>':''}${p.isPackage?packageIncluded(p,basket[p.id]):''}<button class="remove" ${sofaId?`data-sofa-textile-remove="${html(sofaId)}"`:`data-remove="${p.id}"`} aria-label="Fjern ${html(productTitle(p))}">Fjern</button>${parent&&p.rentalPricingMode==='period'&&!addonUnit(p)?'<p class="cart-addon-note">Innhold og farger kan variere.</p>':''}</div>${sofaId?`<div class="cart-line-actions"><button type="button" class="cart-line-action" data-sofa-edit="${html(sofaId)}">Endre</button></div>`:`<div class="quantity"><button data-quantity="${p.id}" data-delta="-1" aria-label="Færre ${html(productTitle(p))}">−</button><span aria-label="Antall">${basket[p.id]}</span><button data-quantity="${p.id}" data-delta="1" aria-label="Flere ${html(productTitle(p))}" ${remaining(p.id,cart,products)<=0?'disabled':''}>+</button></div>`}</div>`;}
function renderCart(){if(!catalogLoaded)return;const packageView=packageCartView(withoutSofas(cart,sofaSetups),products,packageGroups,cartLinks);packageGroups=packageView.saved;document.dispatchEvent(new CustomEvent('rental-delivery-selection',{detail:{basket:rentalBasket(),products,customRequest:customRequest.active}}));refreshPageRecommendations();for(const id of Object.keys(businessChoices))if(!cart[id])delete businessChoices[id];try{localStorage.setItem('konsept-business-choices-v1',JSON.stringify(businessChoices));}catch{}el('customRequestItem').hidden=!customRequest.active;el('customRequestText').disabled=!customRequest.active;el('customRequestText').required=customRequest.active;if(el('customRequestText').value!==customRequest.text)el('customRequestText').value=customRequest.text;el('moduleCartSummary').innerHTML=sofaCards();const ordinaryCart=packageView.loose;el('count').textContent=Object.values(cart).reduce((a,b)=>a+b,0)+(customRequest.active?1:0);el('cartItems').innerHTML=packageView.groups.map(packageCartCard).join('')+(Object.keys(ordinaryCart).length?groupedCart(ordinaryCart,products,cartLinks).map(group=>`<div class="cart-product-group ${group.children.length?'has-addons':''}" role="group" aria-label="${html(group.product.name)}${group.children.length?' med tilvalg':''}">${cartItem(group.product,null,ordinaryCart)}${group.children.map(p=>cartItem(p,group.product,ordinaryCart)).join('')}</div>`).join(''):sofaSetups.length||customRequest.active||packageView.groups.length?'':'<div class="cart-empty" role="status"><h3>Forespørselen din er tom</h3><p>Velg produkter fra utvalget, eller beskriv behovet ditt i skjemaet nedenfor.</p><a class="button dark" href="/utvalg.html?bruk=alle#utvalg">Se produkter</a></div>');el('wallCartActions').innerHTML=products.some(p=>isWall(p)&&cart[p.id])?'<button type="button" class="button button-outline sofa-add-another" data-wall>+ Legg til en bildevegg til</button>':'';el('cartSuggestion').replaceChildren();el('cartSuggestion').hidden=true;renderEstimate();try{localStorage.setItem('konsept-package-groups-v1',JSON.stringify(packageGroups));localStorage.setItem('konsept-cart-v1',JSON.stringify(cart));localStorage.setItem('konsept-sofas-v1',JSON.stringify(sofaSetups));localStorage.setItem('konsept-cart-links-v1',JSON.stringify(cartLinks));}catch{}}
const addedNotice=mountStorefrontFeedback(()=>{if(!el('cart').open)openCart();});
let toastTimer;function toast(text){el('toast').textContent=text;el('toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el('toast').classList.remove('visible'),2200);}
function add(id){const product=products.find(p=>p.id===id);if(!product||product.addonOnly)return;if(product.isPackage){const base=(product.components||[]).find(c=>cart[c.id]&&products.find(x=>x.id===c.id)?.type==='sofa');if(base){offerPackageId=id;offerBaseId=base.id;upgradeToPackage();return;}}if(remaining(id,cart,products)<=0){toast('Maks tilgjengelig beholdning er valgt. Pakker og enkeltobjekter deler lager.');return;}cart[id]=(cart[id]||0)+1;renderCart();renderProducts();addedNotice(product.name+' lagt til');if(product.type==='sofa'&&!product.isPackage){const pack=products.find(p=>p.isPackage&&(p.components||[]).some(c=>c.id===id));if(pack){livingPackage=pack;offerBaseId=id;offerPackageId=pack.id;showPackageOffer();}}}
function hasQuotedPackage(){return packageGroups.some(g=>products.find(p=>p.id===g.packageId)?.packageCustomPricing==='quote');}
function renderEstimate(){
 const empty=!Object.keys(cart).length&&!sofaSetups.length&&!customRequest.active;el('priceEstimate').hidden=empty;el('discountCode').hidden=empty;
 if(!hasQuotedPackage())discount?.refresh();el('discountCode').hidden=empty||hasQuotedPackage();
 const rental=needsRentalDates();if(el('rentalTermsLabel')){el('rentalTermsLabel').hidden=!rental;el('rentalTermsAccepted').disabled=!rental;el('rentalTermsAccepted').required=rental;}const purchases=purchaseBasket(),hasPurchases=Object.keys(purchases).length>0;
 el('rentalDates').hidden=!rental;el('start').disabled=el('end').disabled=!rental;el('start').required=el('end').required=rental;
 el('purchaseDates').hidden=!hasPurchases;
 const quote=rentalEstimate(rentalBasket(),products,el('start').value,el('end').value);
 if(hasQuotedPackage()){quote.hasUnpriced=true;quote.total=null;}if(customRequest.active){quote.hasUnpriced=true;quote.lines.push({quantity:1,name:'Tilpasset forespørsel',plan:null});}
 const purchaseLines=products.filter(p=>purchases[p.id]).map(p=>`<div class="estimate-line"><span>${purchases[p.id]} × ${html(p.name)}<small>Kjøp · pris, tilstand og levering avklares</small></span><strong>${packagePurchasePrice(p,purchases[p.id])===null?'Pris på forespørsel':money(packagePurchasePrice(p,purchases[p.id]))}</strong></div>`).join('');
 el('priceEstimate').innerHTML=`${rental?`<div><span>Valgt leieperiode</span><strong>${quote.days===null?'Velg datoer':quote.days+' døgn'}</strong></div>`:''}${quote.lines.map(line=>`<div class="estimate-line"><span>${line.quantity} × ${html(line.name)}<small>${line.plan?html(planText(line.plan))+' per enhet':'Pris avklares i tilbudet'}</small></span><strong>${line.plan?money(line.plan.total*line.quantity):'Pris på forespørsel'}</strong></div>`).join('')}${purchaseLines}${quote.hasUnpriced&&quote.lines.some(l=>l.plan)?`<div><span>Delpris for prisede leieobjekter</span><strong>${money(quote.knownSubtotal)}</strong></div>`:''}<div class="estimate-total"><span>${hasPurchases?'Samlet pris for forespørselen':'Veiledende leiesum'}</span><strong>${hasPurchases?'Avklares i tilbud':quote.days===null?'–':quote.hasUnpriced?'Avklares i tilbud':money(quote.total)}</strong></div>${quote.saving>0?`<div class="rate-saving"><span>Du sparer mot døgnpris på leieobjektene</span><strong>${money(quote.saving)}</strong></div>`:''}<p>${rental?'Leie beregnes for begge valgte datoer. En uke = 7 døgn, en måned = 30 døgn. Tilvalg prises per påbegynte 30 dager. Vi bruker den rimeligste kombinasjonen for objekter med oppgitt leiepris. ':''}${hasPurchases?'Kjøpspris beregnes ikke ut fra leiepris. Hvilke varer som kan selges, tilstand og kjøpsvilkår avklares i tilbudet. ':''}Transport, oppsett og øvrige kostnader avklares i tilbudet. Forespørselen er uforpliktende.</p>`;
}


function openCart(){if(!ensureRentalUsage(openCart))return;renderPricingScope();el('result').textContent='';el('cart').showModal();}
let savedPurpose='alle';try{savedPurpose=sessionStorage.getItem('konsept-purpose-v1')||'alle';}catch{}
let purpose='alle';
const occasionForPurpose={boligsalg:'Boligsalg',messe:'Messe og stand',fest:'Event og selskap',bedrift:'Bedrift',jul:'Annet'};
function pricingScopeLabel(){return rentalUsageLabels[rentalScope];}
function usageButtons(){return `<div class="rental-usage-options" role="group" aria-label="Velg bruk for leiepriser">${Object.entries(rentalUsageLabels).map(([scope,label])=>`<button type="button" data-rental-scope-choice="${scope}" aria-pressed="${rentalScopeConfirmed&&rentalScope===scope}"><strong>${label}</strong><span>${scope==='standard'?'Møbler til boligfoto og visning ved boligsalg':'Messe, stand, event, arbeidsplass, fest og annen bruk'}</span></button>`).join('')}</div>`;}
function renderPricingScope(){
 const explanation=`<p class="hint">${rentalUsageExplanation} Alle viste leiepriser inkluderer valgt bruk og mva. Transport og eventuelt oppsett avklares i tilbudet.</p>`;
 const catalog=el('catalogPricingScope');if(catalog)catalog.innerHTML=rentalScopeConfirmed?`<p class="rental-selected-usage">Leiepriser for: <strong>${pricingScopeLabel()}</strong></p><p class="hint">${rentalUsageExplanation} Prisene inkluderer valgt bruk og mva.</p><details><summary>Endre bruk</summary>${usageButtons()}</details>`:`<h3>Hva skal du bruke møblene til?</h3><p>Velg bruk for å se riktige leiepriser.</p>${usageButtons()}${explanation}`;
 const cartScope=el('cartPricingScope');if(cartScope)cartScope.innerHTML=`<p class="rental-selected-usage">Valgt bruk: <strong>${rentalScopeConfirmed?pricingScopeLabel():'Velg bruk'}</strong></p><p>${rentalUsageExplanation}</p><details><summary>Endre bruk</summary>${usageButtons()}<p class="hint">Prisene oppdateres for alle valgte produkter. Datoer og antall beholdes.</p></details>`;
 el('pricingChoiceOptions').innerHTML=usageButtons();syncMobileCatalog();
}
function ensureRentalUsage(action){if(rentalScopeConfirmed)return true;pendingUsageAction=action;renderPricingScope();if(!el('pricingChoice').open)el('pricingChoice').showModal();return false;}
function setRentalScope(scope,confirmed=true){
 rentalScope=scope==='messe'?'messe':'standard';rentalScopeConfirmed=confirmed;if(confirmed){savedRentalScope=rentalScope;try{localStorage.setItem('konsept-rental-scope-v1',rentalScope);}catch{}}
 products=applyRentalScope(catalogProducts,rentalScope);if(isCatalogPage){const url=new URL(location.href);if(confirmed)url.searchParams.set('prisbruk',rentalScope);else url.searchParams.delete('prisbruk');history.replaceState(null,'',url.pathname+url.search+url.hash);}renderPricingScope();
 if(catalogProducts.length){for(const id of ['detail','modules','wall'])if(el(id).open)closeSurface(el(id));renderProducts();renderCart();if(isProductPage){const p=products.find(p=>p.id===new URL(location.href).searchParams.get('produkt'));if(el('modules').open)renderModuleBuilder();else if(el('wall').open)refreshWall();else if(el('detail').open&&p){const quantity=el('productQuantity')?.value;openProduct(p);if(quantity&&el('productQuantity')){el('productQuantity').value=quantity;refreshSelection();}}if(p)selectPageProduct(p,'rent',{bruk:purpose,prisbruk:rentalScope});}}
}
function syncRentalPurpose(){if(lastPricingPurpose===purpose)return;const explicit=lastPricingPurpose===null?new URL(location.href).searchParams.get('prisbruk'):null;lastPricingPurpose=purpose;const state=rentalUsageState({purpose,explicit,saved:savedRentalScope});el('occasion').value=purpose==='alle'?(state.scope==='standard'?'Boligsalg':'Annet'):occasionForPurpose[purpose]||'Annet';setRentalScope(state.scope,state.confirmed);}
document.addEventListener('click',event=>{const choice=event.target.closest('[data-rental-scope-choice]');if(!choice)return;const scope=choice.dataset.rentalScopeChoice;if(purpose!=='alle'&&scopeForPurpose(purpose)!==scope){purpose='alle';rememberPurpose();lastPricingPurpose='alle';}el('occasion').value=scope==='standard'?'Boligsalg':scopeForOccasion(el('occasion').value)==='messe'?el('occasion').value:'Annet';setRentalScope(scope);if(isCatalogPage)writePurpose(false);if(el('pricingChoice').open)el('pricingChoice').close();const action=pendingUsageAction;pendingUsageAction=null;action?.();});
document.addEventListener('change',event=>{if(event.target.id==='occasion'){const scope=scopeForOccasion(event.target.value);if(purpose!=='alle'&&scopeForPurpose(purpose)!==scope){purpose='alle';rememberPurpose();lastPricingPurpose='alle';}setRentalScope(scope);if(isCatalogPage)writePurpose(false);}});

function syncMobileCatalog(){
 if(!isCatalogPage||!el('mobileCategoryButton'))return;
 const categoryButtons=[...el('utvalg').querySelectorAll('.filters [data-filter]')].filter(b=>purpose!=='boligsalg'||b.dataset.filter!=='Pakker');
 const selectedCategory=categoryButtons.find(b=>b.dataset.filter===filter)?.textContent||'Alle';
 el('mobileCategoryButton').querySelector('span').textContent='Kategori: '+selectedCategory;
 el('mobileCatalogUsageLabel').textContent=!rentalScopeConfirmed?'Velg bruk for å se leiepriser':purpose==='alle'?pricingScopeLabel():purposes.find(p=>p.id===purpose)?.label||pricingScopeLabel();
 el('mobileChangeUsage').textContent=rentalScopeConfirmed?'Endre':'Velg bruk';
 el('mobileCategoryChoices').innerHTML=categoryButtons.map(b=>`<button type="button" data-mobile-filter="${html(b.dataset.filter)}" aria-pressed="${filter===b.dataset.filter||filter==='Enkeltprodukter'&&b.dataset.filter==='Alle'}">${html(b.textContent)}</button>`).join('');
 el('mobileUsageChoices').innerHTML=purposes.map(p=>`<button type="button" data-mobile-purpose="${p.id}" aria-pressed="${purpose===p.id}">${html(p.id==='alle'?'Alle bruksområder':p.label)}</button>`).join('');
}
function rememberPurpose(){try{sessionStorage.setItem('konsept-purpose-v1',purpose);}catch{}}
