let wallSelection='',wallGroup='Bildevegg';
function wallGroups(){return [...new Set(products.filter(isWall).map(p=>p.wallGroup))];}
function wallProducts(group=wallGroup){return products.filter(p=>isWall(p)&&p.wallGroup===group).sort((a,b)=>(a.wallOrder||0)-(b.wallOrder||0)||a.name.localeCompare(b.name,'nb'));}
function wallSketch(p){return frameSketch(p.wallFrames?.length?p.wallFrames:presetFrames('gallery'),'Skisse: '+p.name);}
function wallCard(group){const variants=wallProducts(group),cover=variants.find(p=>p.wallCover)?.wallCover||variants[0]?.image||'/assets/bildevegg-illustrasjon-hvit.png',from={price:Math.min(...variants.map(p=>p.price)),weekPrice:Math.min(...variants.map(p=>p.weekPrice)),monthPrice:Math.min(...variants.map(p=>p.monthPrice))};return `<article class="wall-card"><button class="product-art" data-wall="${html(group)}" aria-label="Velg ${html(group.toLowerCase())}"><span>BILDER · ILLUSTRASJON</span><img src="${html(cover)}" alt="Illustrasjon av bildevegg">${isKiPhoto(cover)?'<span class="illustration-badge ki-disclosure">'+kiDisclosure+'</span>':''}</button><div class="product-meta"><div><h3>${html(group==='Bildevegg'?'Bildevegg satt sammen av stylist':group)}</h3><p>Velg oppsett – stylisten setter sammen helheten</p></div><button class="button dark module-build-button" data-wall="${html(group)}">Velg din bildevegg ↗</button></div><p class="stock-note">Fra-priser per bildevegg. Stylisten setter sammen helheten.</p>${rateGrid(from)}</article>`;}
function openWall(id='',group=''){const target=products.find(p=>isWall(p)&&p.id===id)||products.find(p=>isWall(p)&&(!group||p.wallGroup===group));if(!target)return;if(!isProductPage){navigateProduct(target.id,'rent',{bruk:purpose,prisbruk:rentalScopeConfirmed?rentalScope:''});return;}selectPageProduct(target,'rent',{bruk:purpose,prisbruk:rentalScopeConfirmed?rentalScope:''});if(!ensureRentalUsage(()=>openWall(id,group)))return;const chosen=products.find(p=>isWall(p)&&p.id===id);wallGroup=chosen?.wallGroup||group||wallGroups()[0];wallSelection=chosen?.id||wallProducts()[0]?.id;if(!wallSelection)return;el('wallQuantity').value='1';el('wallLayouts').innerHTML=wallProducts().map(p=>`<label class="wall-layout"><input type="radio" name="wallLayout" value="${p.id}" ${p.id===wallSelection?'checked':''}>${wallSketch(p)}<strong>${html(wallLabel(p))}</strong><small>${p.priceOnRequest?'Pris på forespørsel':money(p.price)+'/døgn'}</small></label>`).join('');refreshWall();if(el('cart').open)el('cart').close();showSurface(el('wall'),target.name);}
function refreshWall(){const p=products.find(p=>p.id===wallSelection),q=Number(el('wallQuantity').value),valid=p&&Number.isInteger(q)&&q>0&&q<=remaining(p.id,cart,products);el('wallSummary').innerHTML=valid?`<p><strong>${q} × ${html(wallLabel(p))}</strong></p>${rateGrid({...p,price:p.price*q,weekPrice:p.weekPrice*q,monthPrice:p.monthPrice*q})}<p class="hint">Stylistens sammensetning inngår. Størrelser og plassering kan variere noe fra illustrasjonen, men helhetsuttrykket beholdes.</p>`:'<p class="hint">Velg et gyldig antall bildevegger.</p>';el('addWall').disabled=!valid;}
document.addEventListener('click',e=>{const button=e.target.closest('[data-wall]');if(button)openWall('',button.dataset.wall);});
document.addEventListener('change',e=>{if(e.target.name==='wallLayout'){wallSelection=e.target.value;const p=products.find(p=>p.id===wallSelection);if(p)selectPageProduct(p,'rent',{bruk:purpose,prisbruk:rentalScope});}else if(e.target.id!=='wallQuantity')return;refreshWall();});
el('wallQuantity').addEventListener('input',refreshWall);
el('addWall').addEventListener('click',()=>{const p=products.find(p=>p.id===wallSelection),q=Number(el('wallQuantity').value);if(!p||!Number.isInteger(q)||q<1||q>remaining(p.id,cart,products))return;cart[p.id]=(cart[p.id]||0)+q;const previous=Array.isArray(cartLinks[p.id]?.choices)?cartLinks[p.id].choices:[];cartLinks[p.id]={parentId:'',choices:[...previous,{quantity:q,color:'Stylistens sammensetning'}]};renderProducts();renderCart();closeSurface(el('wall'));if(isProductPage)refreshWall();addedNotice('Bildeveggen er lagt til. Du kan legge til en annen.');});

document.addEventListener('change',e=>{if(e.target.id==='tableSize'){const p=oakTables().find(t=>t.id===e.target.value);if(p)openProduct(p);}});

document.addEventListener('change',event=>{if(!['requestTableStylist','tableStylistOccasion'].includes(event.target.id))return;syncTableStyling();refreshSelection();});

document.addEventListener('click',event=>{const button=event.target.closest('[data-table-styling]');if(!button)return;const base=products.find(p=>p.id===button.dataset.tableStyling);if(!base)return;openProduct(base);document.querySelector('.styling-inspiration')?.setAttribute('open','');document.querySelector('.table-styling')?.scrollIntoView({block:'start'});el('requestTableStylist')?.focus({preventScroll:true});});

document.addEventListener('change',event=>{if(event.target.id!=='christmasTreeSize')return;const pack=christmasTreePackages().find(p=>p.id===event.target.value);if(pack)openProduct(pack);});

document.addEventListener('change',event=>{const select=event.target.closest('[data-business-mode]');if(!select)return;const id=select.dataset.businessMode;if(!businessPackageIds.has(id)||!cart[id])return;businessChoices[id]=acquisitionMode(select.value);renderCart();});

document.addEventListener('click',event=>{const button=event.target.closest('[data-business-custom]');if(!button)return;const p=products.find(p=>p.id===button.dataset.businessCustom);if(!p||!businessPackageIds.has(p.id))return;const message='Jeg ønsker en tilpasset bedriftsløsning med utgangspunkt i '+p.name+'. Jeg ønsker leie med kjøpsmulighet etter leieperioden. Leiepris og kjøpspris avklares når leietilbudet utarbeides.';if(!customRequest.text.includes(message))customRequest.text=[customRequest.text,message].filter(Boolean).join('\n\n');closeSurface(el('detail'));el('occasion').value='Bedrift';openCustomRequest();});

function rentalCardTitle(p){return p.category==='Belysning'&&rentalVariants(p,products).length>1?variantFields(p).variantGroup:productTitle(p);}
function rentalColourChoices(p,detail=false){const variants=rentalVariants(p,products);if(variants.length<2)return '';return `<div class="rental-colours"><p>${detail?'Velg farge · Valgt: '+html(variantFields(p).variantLabel):'Finnes i '+variants.length+' farger til leie'}</p><div class="variant-swatches" role="group" aria-label="Velg farge">${variants.map(x=>`<button type="button" data-rental-colour="${x.id}" class="variant-swatch" style="--swatch:${variantColour(x)}" aria-label="Velg farge ${html(variantFields(x).variantLabel)}" title="${html(variantFields(x).variantLabel)} · ${remaining(x.id,cart,products)} stk. tilgjengelig" ${detail?'aria-pressed="'+(x.id===p.id)+'"':''}><i aria-hidden="true"></i><span>${html(variantFields(x).variantLabel)}${detail?' · '+remaining(x.id,cart,products)+' stk.':''}</span></button>`).join('')}</div></div>`;}
function productVariantOptions(p){return rentalColourChoices(p,true);}
document.addEventListener('click',event=>{const button=event.target.closest('[data-rental-colour]');if(!button)return;const next=products.find(p=>p.id===button.dataset.rentalColour);if(!next||!rentalVariants(next,products).some(p=>p.id===next.id))return;const quantity=el('detail').open?Number(el('productQuantity')?.value)||1:1;openProduct(next);el('productQuantity').value=Math.max(1,Math.min(quantity,remaining(next.id,cart,products)));refreshSelection();});


discount=mountDiscount(el('discountCode'),()=>({mode:'rent',basket:rentalBasket(),start:el('start').value,end:el('end').value,scope:rentalScope}));

const requestStylistHint=document.querySelector('.styling-choice>.hint');if(requestStylistHint)requestStylistHint.textContent=stylistProvider+' Vi hjelper med møblene og dekoren du leier. Tjenesten prises separat i tilbudet.';
